#include <bits/stdc++.h>
using namespace std;

string removeDuplicates(string s, char ch)
{

    // If length of string is 1 or 0
    if (s.length() <= 1)
    {
        return s;
    }

    int i = 0;
    while (i < s.length())
    {
        if (i + 1 < s.length() && s[i] == s[i + 1])
        {
            int j = i;
            while (j + 1 < s.length() && s[j] == s[j + 1])
            {
                j++;
            }
            char lastChar = i > 0 ? s[i - 1] : ch;

            string remStr = removeDuplicates(
                s.substr(j + 1, s.length()), lastChar);

            s = s.substr(0, i);
            int k = s.length(), l = 0;

            // Recursively remove all the adjacent
            // characters formed by removing the
            // adjacent characters
            while (remStr.length() > 0 && s.length() > 0 && remStr[0] == s[s.length() - 1])
            {

                // Have to check whether this is the
                // repeated character that matches the
                // last char of the parent String
                while (remStr.length() > 0 && remStr[0] != ch && remStr[0] == s[s.length() - 1])
                {
                    remStr = remStr.substr(1, remStr.length());
                }
                s = s.substr(0, s.length() - 1);
            }
            s = s + remStr;
            i = j;
        }
        else
        {
            i++;
        }
    }
    return s;
}

class Solution
{

    string removeduplicates(string s)
    {
        int n = s.length();
        if (n == 0 || n == 1)
            return s;

        if (s[0] == s[1])
        {
            int idx = 0;
            while (idx < n && s[0] == s[idx])
            {
                idx++;
            }
            return removeduplicates(s.substr(idx));
        }

        return s[0] + removeduplicates(s.substr(1));
    }

public:
    string rremove1(string s)
    {
        // code here
        string newS;

        while (1)
        {
            newS = removeduplicates(s);
            if (newS == s)
                break;

            s = newS;
        }

        return newS;
    }
    string rremove(string s)
    {
        while (1)
        {
            string tmp;
            int i = 0;
            int n = s.length();
            while (i < n)
            {
                int j = i + 1;
                while (j < n && s[i] == s[j])
                    j++;

                if (i + 1 == j)
                {
                    tmp += s[i];
                }
                i = j;
            }

            if (tmp.size() == s.size())
                break;

            s = tmp;
        }

        return s;
    }
};

